<?php
require __DIR__.'/../includes/modules.php';$user=require_role('admin');$error='';$edit=[];
if(isset($_GET['edit'])){$edit=query_rows('SELECT * FROM attendance WHERE id=?',[record_id($_GET['edit'])])[0]??null;if(!$edit)missing();}
if(post()){check_csrf();try{$id=empty($_POST['id'])?null:record_id($_POST['id']);if($id&&!query_rows('SELECT id FROM attendance WHERE id=?',[$id]))missing();$action=$_POST['action']??'';
if($action==='delete'){if(!$id)throw new InvalidArgumentException('Choose a record.');execute_sql('DELETE FROM attendance WHERE id=?',[$id]);}
elseif($action==='save'){$employee=employee_value();$date=date_value('attendance_date');$status=choice('status',['Present','Absent','Late','Half Day','Week Off','Leave']);$in=text_value('check_in',8,false);$out=text_value('check_out',8,false);foreach([$in,$out] as $t)if($t!==''&&!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/D',$t))throw new InvalidArgumentException('Enter valid times.');if($out!==''&&($in===''||strtotime($out)<=strtotime($in)))throw new InvalidArgumentException('Check-out must follow check-in on the same day.');if(in_array($status,['Absent','Week Off','Leave'],true)&&($in!==''||$out!==''))throw new InvalidArgumentException('Absent, week off and leave records cannot have check-in/out times.');$args=[$employee,$date,$status,$in?:null,$out?:null];if($id){$args[]=$id;execute_sql('UPDATE attendance SET employee_id=?,attendance_date=?,status=?,check_in=?,check_out=? WHERE id=?',$args);}else execute_sql('INSERT INTO attendance (employee_id,attendance_date,status,check_in,check_out) VALUES (?,?,?,?,?)',$args);}
else throw new InvalidArgumentException('Invalid action.');flash('Attendance saved.');redirect('admin/attendance.php');}catch(InvalidArgumentException|PDOException $e){if($e instanceof PDOException&&$e->getCode()!=='23000')throw $e;$error=$e instanceof PDOException?'Attendance already exists for this employee and date. Edit that record.':$e->getMessage();$edit=$_POST;}}
page_start('Attendance',$user);error_notice($error);?><section class="card"><h2>Add / Edit Attendance</h2><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><div class="form-grid"><?php select_field('employee_id','Employee',employee_options(),$edit['employee_id']??'');input_field('attendance_date','Date',$edit['attendance_date']??date('Y-m-d'),'date');select_field('status','Status',options(['Present','Absent','Late','Half Day','Week Off','Leave']),$edit['status']??'Present');input_field('check_in','Check-in',$edit['check_in']??'','time',false);input_field('check_out','Check-out',$edit['check_out']??'','time',false);?></div><div class="actions"><button class="btn btn-primary" name="action" value="save">Save Attendance</button><a class="btn btn-secondary" href="attendance.php">Cancel</a></div></form></section><?php require __DIR__.'/../includes/attendance-list.php';page_end();
